#include <vector>
#include <iostream>

int main() {
    std::vector<int> c1 = {1, 2, 5};
    std::vector<int> c2 = {1, 2, 4, 6};
    std::vector<int> c3 = {1, 2, 5};

    // Equality (same size and elements)
    std::cout << "c1 == c3: " << (c1 == c3) << "\n"; // True (1)

    // Lexicographical Comparison (1, 2, 5 vs 1, 2, 4)
    // Mismatch at index 2: 5 is not < 4
    std::cout << "c1 < c2: " << (c1 < c2) << "\n"; // False (0)

    // Lexicographical Comparison (1, 2, 4, 6 vs 1, 2, 5)
    // c2 is considered less than c1
    std::cout << "c2 < c1: " << (c2 < c1) << "\n"; // True (1)
}
